import sys,os,json,random,subprocess,struct
sys.path.insert(0,'/workspace/project');sys.path.insert(0,'/workspace/tmp')
from wire import packet,payload,NAMES,MASK
from refcollector import run_case
rnd=random.Random(12345)

def make_case():
    prim=rnd.choice(NAMES)
    mode=rnd.choice([2,3]);root=rnd.randrange(4)
    K=1 if prim=='barrier' else rnd.randint(1,10)
    if prim=='reducescatter':
        K=rnd.choice([4,8,12,16])
    D=0 if prim=='barrier' else rnd.randint(1,5)
    N=rnd.randint(1,6)
    start=rnd.choice([0,1,5,0xfffff0,0xffffff,0xffff00,rnd.randrange(1<<24)])
    events=[]
    # random events count
    for z in range(rnd.randint(0,25)):
        typ=rnd.choices(['data','ack','wire','budget','flush','retry','snap'],[12,5,2,2,1,2,1])[0]
        if typ=='data':
            r=rnd.randrange(4)
            count=rnd.randint(1,min(3,K))
            step=rnd.choice([0,1,-1,2,-2])
            # choose p such that valid
            if step==0:
                p=rnd.randrange(K)
            elif step>0:
                p=rnd.randrange(0,K-(count-1)*step)
            else:
                p=rnd.randrange((count-1)*(-step),K)
            op={'op':'data','rank':r,'p':p,'count':count,'step':step}
            if rnd.random()<.3:op['seed']=rnd.randrange(1<<32)
            if count==1 and rnd.random()<.3:
                op['values']=[rnd.randrange(1<<32) for _ in range(D)]
            if rnd.random()<.15:
                op['xor']=[[rnd.randint(0,57+4*D),rnd.randrange(256)] for _ in range(rnd.randint(0,2))]
            events.append(op)
        elif typ=='ack':
            events.append({'op':'ack','rank':rnd.randrange(4),'upto':rnd.randint(0,3*K+1)})
        elif typ=='wire':
            # sometimes mutate a valid packet, sometimes random hex
            if rnd.random()<.7:
                rr=rnd.randrange(4);p=rnd.randrange(K)
                pl=payload(rnd.randrange(1<<32),p,rr,D)
                fr=bytearray(packet(rr,(start+p)&MASK,pl))
                for _ in range(rnd.randint(0,2)):
                    fr[rnd.randrange(len(fr))]^=rnd.randrange(256)
                h=fr.hex()
            else:
                n=rnd.randrange(0,100);h=bytes(rnd.randrange(256) for _ in range(n)).hex()
            events.append({'op':'wire','rank':rnd.randrange(4),'hex':h})
        elif typ=='budget':
            events.append({'op':'budget','n':rnd.choice([-1,0,1,2,5,10])})
        elif typ=='flush':events.append({'op':'flush'})
        elif typ=='retry':events.append({'op':'retry','rank':rnd.randrange(4)})
        else:events.append({'op':'snap','tag':rnd.choice(['a','b','x','Δ'])})
    c={'primitive':prim,'mode':mode,'root':root,'segments':K,'words':D,'capacity':N,'start':start,'events':events,'trace':rnd.randint(0,32)}
    return c

def invoke(req):
    p=subprocess.run([sys.executable,'/workspace/project/solver.py'],input=json.dumps(req).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode:raise RuntimeError(p.stderr.decode())
    return json.loads(p.stdout)

bad=0
for batch in range(50):
    cases=[make_case() for _ in range(rnd.randint(1,8))]
    req={'cases':cases}
    out=invoke(req)['cases']
    for i,c in enumerate(cases):
        try:exp=run_case(c)
        except Exception as e:
            print('REF ERR',e,c);raise
        if out[i]!=exp:
            print('MISMATCH batch',batch,'case',i,c['primitive'],c['mode'],c)
            for k in exp:
                if out[i][k]!=exp[k]:
                    print(' key',k);print(' C ',out[i][k]);print(' R ',exp[k])
            bad+=1
            if bad>=3:sys.exit(1)
    print('batch',batch,'ok',file=sys.stderr)
print('ALL OK')
PY
